def site_label(fx, c: int):
    return next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)


def link_labels(fx) -> tuple:
    """The x-trivial LINK reflections: ODD p_t, e_x = +1, p_x = 0."""
    return tuple(l for l in fx.link_labels if l[2] == 1 and l[3] == 0)


def blocks_of(P: sp.Matrix, lx: int) -> tuple:
    return P[:lx, :lx], P[:lx, lx:], P[lx:, lx:]


def bench_sub(fx, c: int, sigma=BENCH_SIGMA, mass=BENCH_MASS, st=BENCH_ST,
              sx=BENCH_SX) -> dict:
    sub = b166.carrier_substitution(fx, b166.graded_carrier(fx, c, sigma))
    sub[SX] = sx
    sub[MASS] = mass
    sub[ST] = st
    return sub


def flat_carrier(fx) -> dict:
    """The committed FLAT carrier: nu = a = mu = 1, every shear zero."""
    flat: dict = {}
    for key in fx.CELLS:
        flat[fx.NU[key]] = sp.Integer(1)
        flat[fx.A[key]] = sp.Integer(1)
        flat[fx.B[key]] = sp.Integer(0)
        flat[fx.MU[key]] = sp.Integer(1)
    return flat


def disp2_operator(fx, W: sp.Matrix, backward: bool = False) -> dict:
    """THE IMPOSED displacement-2 operator: a pure cover time-shift-by-2.

    IMPOSED, NOT DERIVED, and gate B measures why the framework cannot make it:
    the committed healed construction is cell-local with displacement support
    {-1, 0}.  The word "differential" is struck: gate E measures d_2^2 != 0.
    """
    out: dict = {}
    ct, lx = fx.COVER_T, fx.LX
    for t in range(ct):
        nxt = (t - 2) % ct if backward else (t + 2) % ct
        for y in range(lx):
            for x in range(lx):
                if W[y, x] != 0:
                    out[(lx * nxt + y, lx * t + x)] = W[y, x]
    return sclean(out)


def first_order(fx, hodge, diff) -> dict:
    """THE COMMITTED RECIPE i(H d + d^H H), quotiented -- applied to any d."""
    return fx.quotient(
        sscale(sadd(smul(hodge, diff), smul(sdagger(diff), hodge)), I))


def second_order(fx, hodge, da, db) -> dict:
    """da^H H db + db^H H da, quotiented -- the Wilson-class cross form."""
    return fx.quotient(sadd(smul(sdagger(da), smul(hodge, db)),
                            smul(sdagger(db), smul(hodge, da))))


def generic_slice_blocks(fx) -> dict:
    """A FULLY NON-HERMITIAN operator with independent blocks at every pair."""
    lx, t = fx.LX, fx.PHYS_T
    out: dict = {}
    for a in range(t):
        for b in range(t):
            for i in range(lx):
                for j in range(lx):
                    out[(lx * a + i, lx * b + j)] = (
                        sp.Symbol(f"q{a}_{b}_{i}{j}r", real=True)
                        + I * sp.Symbol(f"q{a}_{b}_{i}{j}i", real=True))
    return sclean(out)


def two_slice_local(fx) -> dict:
    """A generic Hermitian {0, +-1}-local operator -- Block 167's census object."""
    lx, t = fx.LX, fx.PHYS_T
    out: dict = {}
    for a in range(t):
        for i in range(lx):
            for j in range(lx):
                val = (sp.Symbol(f"e{a}_{i}{j}r", real=True)
                       + I * sp.Symbol(f"e{a}_{i}{j}i", real=True))
                out[(lx * a + i, lx * a + j)] = val
                out[(lx * a + j, lx * a + i)] = sp.conjugate(val)
    for a in range(t):
        nxt = (a + 1) % t
        for i in range(lx):
            for j in range(lx):
                val = (sp.Symbol(f"f{a}_{i}{j}r", real=True)
                       + I * sp.Symbol(f"f{a}_{i}{j}i", real=True))
                out[(lx * nxt + i, lx * a + j)] = val
                out[(lx * a + j, lx * nxt + i)] = sp.conjugate(val)
    return sclean(out)


def inhomogeneous_connection(fx, gsym: dict, hsym: dict | None = None) -> dict:
    """THE COMMITTED healed construction with a PER-TEMPORAL-LINK coupling.

    Byte-for-byte the committed constructor, except that the cell anchored at
    cover time t -- the temporal link (t, t+1) -- carries its OWN coupling g_t,
    and optionally its own spatial coupling h_t.  A PREMISE-CLASS EXTENSION,
    measured and NOT adopted.  Gate D pins it: at g_l = s_t (and h_l = s_x) it
    reproduces the LANDED healed edge differentials entry for entry.
    """
    rt, rx = b105.shift_lifts()
    local_d: dict = {}
    for origin in ORIGINS:
        gauge = (rt ** origin[0]) * (rx ** origin[1])
        out: dict = {}
        for anchor in fx.chart_cells(origin):
            t = anchor[0] % fx.COVER_T
            gx = SX if hsym is None else hsym[t]
            local = I * (gx * EX + gsym[t] * ET)
            block = sp.expand(gauge.H * local * gauge)
            sites = fx.cell_sites(*anchor)
            for p in range(4):
                for q in range(4):
                    if block[p, q] != 0:
                        key = (sites[p], sites[q])
                        out[key] = out.get(key, 0) + block[p, q]
        local_d[origin] = sclean(out)
    star = sadd(local_d[(0, 0)], sscale(local_d[(1, 0)], -1))
    return {(CHART_INDEX[a], CHART_INDEX[b]): sadd(
        local_d[a], sscale(star, HEALING_WEIGHTS[CHART_INDEX[b]]
                           - HEALING_WEIGHTS[CHART_INDEX[a]]))
        for a in ORIGINS for b in ORIGINS}


def signed_displacements(fx, matrix: dict) -> tuple:
    half = fx.PHYS_T // 2
    out = set()
    for (i, j) in matrix:
        raw = (j // fx.LX) - (i // fx.LX)
        out.add(((raw + half) % fx.PHYS_T) - half)
    return tuple(sorted(out))


def positive_moduli(fx) -> set:
    """The strictly positive cone symbols: nu > 0, a > 0, mu > 0.  Only the
    shear b can be negative inside the physical cone."""
    return set(fx.NU.values()) | set(fx.A.values()) | set(fx.MU.values())


def alternating_cone_diagonal(fx, M: sp.Matrix) -> tuple:
    """Is diag(M) = (-1)^x . (s_t/4) . (a POSITIVE cone sum), with no shear?

    A Hermitian matrix whose diagonal carries BOTH signs has a negative
    eigenvalue -- e_x^H M e_x = M_xx -- so this predicate is, by the PRINCIPAL
    SUBMATRIX criterion, a PSD obstruction on any matrix having M as a principal
    submatrix.  That is the checker's route and it is the airtight one.
    """
    pos = positive_moduli(fx)
    signs = []
    for x in range(fx.LX):
        entry = sp.expand(M[x, x])
        if entry == 0:
            return False, ()
        coeff = sp.expand(sp.diff(entry, ST))
        if sp.expand(entry - ST * coeff) != 0:
            return False, ()                     # not purely linear in s_t
        poly = sp.Poly(coeff, *sorted(pos, key=str))
        if not poly.free_symbols <= pos:
            return False, ()                     # a shear leaked in
        coeffs = list(poly.coeffs())
        if not (all(c > 0 for c in coeffs) or all(c < 0 for c in coeffs)):
            return False, ()
        signs.append(1 if coeffs[0] > 0 else -1)
    alternates = all(signs[x] == -signs[x - 1] for x in range(1, len(signs)))
    return alternates, tuple(signs)


# ---------------------------------------------------------------------------
# B. the banners and the rebuild anchors
# ---------------------------------------------------------------------------
def convention_probe() -> tuple:
    """The two LANDED helpers, called on the same three matrices."""
    probes = (
        sp.diag(1, 1, 1, 1, 0, 0, 0, 0),
        sp.diag(1, 1, 1, 1, -1, -1, -1, -1),
        sp.zeros(8, 8),
    )
    pairs = []
    for matrix in probes:
        try:
            old = tuple(b163.congruence_inertia(matrix))
        except Exception:                        # the landed helper's raise path
            old = ()
        pairs.append((old, tuple(inertia(matrix))))
    landed_psd = pairs[0][0][2] == 0 and pairs[0][0][0] > 0
    here_psd = pairs[0][1][1] == 0 and pairs[0][1][0] > 0
    orders_differ = any(a != b for a, b in pairs)
    return tuple(pairs), landed_psd, here_psd, orders_differ


def anchor_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    for tag in TAGS:
        fx = fixtures[tag]
        bench = benches[tag]
        lx = fx.LX
        landed, _ = b166.region_pairing(
            fx, SLICE_C, fx.edge_d[(0, 0)], [SLICE_C - 1, SLICE_C])
        d1 = fx.edge_d[(0, 0)]
        cover = fx.COVER_T * lx
        out[tag] = {
            "bench_is_landed":
                sp.expand(bench["P0"] - landed) == sp.zeros(2 * lx, 2 * lx),
            "d1_cover_displacements": tuple(sorted(
                {(j // lx) - (i // lx) for (i, j) in d1})),
            "d1_squared_zero": sclean(smul(d1, d1)) == {},
            "d1_rank": dense(d1, cover, cover).rank(),
            "cover_dim": cover,
            "corner_hollow":
                sp.expand(bench["P0"][lx:, lx:]) == sp.zeros(lx, lx),
            "b_free_of_st":
                ST not in free_symbols_of(sp.expand(bench["P0"][:lx, :lx])),
            "b_is_mass_linear": sp.expand(
                bench["P0"][:lx, :lx]
                - MASS * sp.diff(bench["P0"][:lx, :lx], MASS))
                == sp.zeros(lx, lx),
            "c_is_linear_in_st": sp.expand(
                bench["P0"][:lx, lx:]
                - ST * sp.diff(bench["P0"][:lx, lx:], ST)) == sp.zeros(lx, lx),
            "c_is_mass_free":
                MASS not in free_symbols_of(sp.expand(bench["P0"][:lx, lx:])),
            "involutive": len(fx.involutive),
            "x_trivial": len(fx.x_trivial),
            "link_directions": len(link_labels(fx)),
        }
    return out


# ---------------------------------------------------------------------------
# C. H1 -- THE LINK-REFLECTION COMPLETION
# ---------------------------------------------------------------------------
def link_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {"dictionary": {}, "census": {}, "mass_parity": {},
                 "alternation": {}, "transport": {}}

    # --- H1(a) the dictionary, on a FULLY NON-HERMITIAN generic operator ----
    for tag in TAGS:
        fx = fixtures[tag]
        c, lx, T = SLICE_C, fx.LX, fx.PHYS_T
        rows = fx.slice_rows(c, c + 1)
        Qg = generic_slice_blocks(fx)
        md = dense(Qg, fx.PHYS, fx.PHYS)
        identity_ok = True
        for lab in link_labels(fx):
            pt = lab[1]
            desc = fx.descent(lab)
            sgn = {a: next(int(v) for (i, j), v in desc.items() if i // lx == a)
                   for a in range(T)}
            th = {a: (pt - a) % T for a in range(T)}
            P = sp.expand(fx.pairing(desc, Qg, rows))
            B, C, K = blocks_of(P, lx)

            def blk(a, b):
                return sp.expand(md[fx.slice_rows(a), fx.slice_rows(b)])

            pB = sp.expand(sgn[c] * blk(th[c], c))
            pK = sp.expand(sgn[c + 1] * blk(th[c + 1], c + 1))
            pC = sp.expand((sgn[c] * blk(th[c], c + 1)
                            + sgn[c + 1] * blk(th[c + 1], c).H) / 2)
            delta = pt - 2 * c - 1
            identity_ok &= bool(
                sp.expand(B - (pB + pB.H) / 2) == sp.zeros(lx, lx)
                and sp.expand(K - (pK + pK.H) / 2) == sp.zeros(lx, lx)
                and sp.expand(C - pC) == sp.zeros(lx, lx)
                and th[c] == (c + 1 + delta) % T
                and th[c + 1] == (c + delta) % T
                and delta % 2 == 0)
        out["dictionary"][tag] = {
            "identity": identity_ok,
            "free_symbols": len(free_symbols_of(md)),
            "directions": len(link_labels(fx)),
        }

    # --- H1(a) THE DELTA-PARITY LIVENESS LAW, general T at L_x = 2 ----------
    law_rows = []
    law_ok = True
    for T in GENERAL_T:
        fx = b165.Fixture(2 * T, GENERAL_T_LX, f"{2 * T}x{GENERAL_T_LX}")
        c, lx = SLICE_C, GENERAL_T_LX
        rows = fx.slice_rows(c, c + 1)
        base = two_slice_local(fx)
        live, pred = [], []
        for lab in link_labels(fx):
            delta = (lab[1] - 2 * c - 1) % T
            K = sp.expand(fx.pairing(fx.descent(lab), base, rows))[lx:, lx:]
            live.append(K != sp.zeros(lx, lx))
            pred.append(((delta - 1) % T) in (0, 1, T - 1))
        law_ok &= live == pred
        law_rows.append((T, sum(live), len(live)))
    out["liveness_law"] = {"ok": law_ok, "rows": tuple(law_rows),
                           "lx": GENERAL_T_LX}

    # --- the ODD-T third class (delta = 1), a PREMISE-CLASS EXTENSION -------
    odd_rows = []
    for T in ODD_T:
        fx = b165.Fixture(2 * T, GENERAL_T_LX, f"{2 * T}x{GENERAL_T_LX}")
        c, lx = SLICE_C, GENERAL_T_LX
        hodge = b166.ssubs(fx.H_free, b166.region_pin(fx, [c - 1, c]))
        act = fx.quotient_action(fx.edge_d[(0, 0)], hodge, MASS)
        for lab in link_labels(fx):
            if (lab[1] - 2 * c - 1) % T != 1:
                continue
            P = sp.expand(fx.pairing(fx.descent(lab), act,
                                     fx.slice_rows(c, c + 1)))
            B, _, K = blocks_of(P, lx)
            trace = sp.expand(sp.trace(K))
            pos = sorted(positive_moduli(fx), key=str)
            negative = all(
                co < 0 for co in
                sp.Poly(sp.expand(sp.diff(trace, MASS)), *pos).coeffs())
            odd_rows.append((T, lab[1], negative,
                             all(sp.expand(B[x, x]) == 0 for x in range(lx))))
    out["odd_t"] = tuple(odd_rows)

    # --- H1(b) the census, and the closing theorem for every direction -----
    for tag in TAGS:
        fx = fixtures[tag]
        c, lx, T = SLICE_C, fx.LX, fx.PHYS_T
        rows = fx.slice_rows(c, c + 1)
        act = benches[tag]["act"]
        generic = two_slice_local(fx)
        census, alternation, transport = [], [], []
        for lab in link_labels(fx):
            pt = lab[1]
            delta = (pt - 2 * c - 1) % T
            desc = fx.descent(lab)
            Kg = sp.expand(fx.pairing(desc, generic, rows))[lx:, lx:]
            P = sp.expand(fx.pairing(desc, act, rows))
            B, C, K = blocks_of(P, lx)
            k_live = K != sp.zeros(lx, lx)
            b_hollow = B == sp.zeros(lx, lx)
            c_zero = C == sp.zeros(lx, lx)
            alt, signs = alternating_cone_diagonal(fx, B)
            if b_hollow and not k_live:
                theorem = "mass parity"
            elif b_hollow and not c_zero:
                theorem = "zero-block lemma"
            elif alt:
                theorem = "staggered alternation"
            else:
                theorem = "UNCLOSED"
            census.append((pt, delta, Kg != sp.zeros(lx, lx), k_live,
                           sp.expand(sp.trace(K)) == 0, b_hollow, c_zero, alt,
                           theorem))
            if alt:
                # THE PRINCIPAL-SUBMATRIX WITNESS, exact at the bench carrier.
                Bb = sp.expand(B.subs(bench_sub(fx, c)))
                alternation.append((pt, signs,
                                    any(Bb[x, x] < 0 for x in range(lx)),
                                    sp.expand(P[:lx, :lx] - B)
                                    == sp.zeros(lx, lx)))
            if k_live:
                syms = free_symbols_of(sp.expand(K))
                holo = connection_gen(fx, I * SX, GRE + I * GIM, ET)
                act_h = fx.quotient_action(holo[(0, 0)], benches[tag]["hodge"],
                                           MASS)
                Kh = sp.expand(fx.pairing(desc, act_h, rows))[lx:, lx:]
                transport.append((
                    pt,
                    bool(syms & positive_moduli(fx)),
                    ST in syms,
                    SX in syms,
                    sp.expand(Kh - K) != sp.zeros(lx, lx),
                ))
        out["census"][tag] = tuple(census)
        out["alternation"][tag] = tuple(alternation)
        out["transport"][tag] = tuple(transport)

        # --- MASS PARITY at delta = 0, written out exactly ------------------
        lab = next(l for l in link_labels(fx)
                   if (l[1] - 2 * c - 1) % T == 0)
        desc = fx.descent(lab)
        P = sp.expand(fx.pairing(desc, act, rows))
        C = P[:lx, lx:]
        md = dense(act, fx.PHYS, fx.PHYS)
        s1 = next(int(v) for (i, j), v in desc.items() if i // lx == c)
        s2 = next(int(v) for (i, j), v in desc.items() if i // lx == c + 1)
        pred = sp.expand(
            (s1 * md[fx.slice_rows(c + 1), fx.slice_rows(c + 1)]
             + s2 * md[fx.slice_rows(c), fx.slice_rows(c)].H) / 2)
        out["mass_parity"][tag] = {
            "identity": sp.expand(C - pred) == sp.zeros(lx, lx),
            "mass_linear_diagonal": all(
                sp.expand(sp.diff(C[x, x], MASS)) != 0 for x in range(lx)),
            "c_nonzero": C != sp.zeros(lx, lx),
            "inertia": tuple(inertia(sp.expand(P.subs(bench_sub(fx, c))))),
        }
    return out


# ---------------------------------------------------------------------------
# D. H2 -- THE INHOMOGENEOUS EXTENSION
# ---------------------------------------------------------------------------
def inhomogeneous_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {"pins": {}, "cells": {}}
    for tag in TAGS:
        fx = fixtures[tag]
        c, lx = SLICE_C, fx.LX
        gsym = {t: sp.Symbol(f"gl_{t}", real=True) for t in range(fx.COVER_T)}
        hsym = {t: sp.Symbol(f"hl_{t}", real=True) for t in range(fx.COVER_T)}
        dg = inhomogeneous_connection(fx, gsym)
        dgh = inhomogeneous_connection(fx, gsym, hsym)
        gh_pin_substitution = {gsym[t]: ST for t in gsym}
        gh_pin_substitution.update({hsym[t]: SX for t in hsym})
        out["pins"][tag] = {
            "g_pin": all(
                sclean(b166.ssubs(dg[k], {gsym[t]: ST for t in gsym}))
                == sclean(fx.edge_d[k]) for k in fx.EDGE_KEYS),
            "gh_pin": all(
                sclean(b166.ssubs(dgh[k], gh_pin_substitution))
                == sclean(fx.edge_d[k]) for k in fx.EDGE_KEYS),
            "chart_pairs": len(fx.EDGE_KEYS),
        }
        cells = {}
        for region, hodge in (("region", benches[tag]["hodge"]),
                              ("offregion", fx.H_free)):
            builders = {
                "committed action":
                    lambda d, h=hodge: fx.quotient_action(d, h, MASS),
                "quotient(d^H H d)":
                    lambda d, h=hodge: second_order(fx, h, d, d),
                "quotient(i(H d + d^H H))":
                    lambda d, h=hodge: first_order(fx, h, d),
            }
            for name in INHOMO_OBJECTS:
                for coupling, diff in (("g_l", dg[(0, 0)]),
                                       ("g_l & h_l", dgh[(0, 0)])):
                    K = corner_of(fx, builders[name](diff), c)
                    free = free_symbols_of(sp.expand(K))
                    cells[(region, name, coupling)] = (
                        all(sp.expand(K[x, x]) == 0 for x in range(lx)),
                        K != sp.zeros(lx, lx),
                        any(s in free for s in
                            list(gsym.values()) + list(hsym.values())),
                    )
        out["cells"][tag] = cells
    return out


# ---------------------------------------------------------------------------
# E. H3 -- THE REOPENING CLAIM, REPRODUCED THEN DISPOSED ON FOUR GROUNDS
# ---------------------------------------------------------------------------
def disposal_probe(fixtures: dict, benches: dict, deep: bool) -> dict:
    out: dict = {}
    for tag in TAGS:
        fx = fixtures[tag]
        c, lx = SLICE_C, fx.LX
        cover = fx.COVER_T * lx
        hodge = benches[tag]["hodge"]
        act = benches[tag]["act"]
        rows = fx.slice_rows(c, c + 1)
        desc = fx.descent(site_label(fx, c))
        d1 = fx.edge_d[(0, 0)]
        d2 = disp2_operator(fx, I * G2 * sp.eye(lx))
        dq = first_order(fx, hodge, d2)
        md = dense(dq, fx.PHYS, fx.PHYS)
        P0 = benches[tag]["P0"]
        Pf = sp.expand(fx.pairing(desc, sadd(act, dq), rows))
        K = corner_of(fx, dq, c)
        row: dict = {}

        # === THE SOLVE'S ARITHMETIC, REPRODUCED EXACTLY =====================
        row["displacements"] = signed_displacements(fx, dq)
        row["touches_b"] = sp.expand(
            md[fx.slice_rows(c), fx.slice_rows(c)]) != sp.zeros(lx, lx)
        row["touches_c"] = sp.expand(
            md[fx.slice_rows(c), fx.slice_rows(c + 1)]) != sp.zeros(lx, lx)
        wanted = sum(sp.Symbol(name, real=True)
                     for name in CORNER_DIAGONAL_SYMBOLS[tag])
        row["corner_diagonal_entry"] = sp.expand(
            K[0, 0] - G2 * wanted / 4) == 0
        row["corner_not_traceless"] = sp.expand(sp.trace(K)) != 0
        # the cross sector -- E1, one of the two corrections H3 DOES earn
        d2w = disp2_operator(fx, I * generic_V(lx, "w"))
        cross = corner_of(fx, second_order(fx, hodge, d1, d2w), c)
        row["cross_not_traceless"] = sp.expand(sp.trace(cross)) != 0
        d2x = disp2_operator(fx, I * sp.diag(
            *[sp.Symbol(f"wd_{k}", real=True) for k in range(lx)]))
        row["cross_diagonal_w_is_traceless"] = sp.expand(sp.trace(
            corner_of(fx, second_order(fx, hodge, d1, d2x), c))) == 0
        # the anti-Hermitian cover class -- E3, reproduced
        cov1 = sscale(sadd(smul(hodge, d1), smul(sdagger(d1), hodge)), I)
        cov2 = sscale(sadd(smul(hodge, d2), smul(sdagger(d2), hodge)), I)
        row["same_hermiticity_class"] = (
            sadd(sdagger(cov1), cov1) == {} and sadd(sdagger(cov2), cov2) == {})
        # E7, the other correction H3 DOES earn: it moves C
        sub = bench_sub(fx, c)
        c0 = sp.expand(Pf.subs(sub).subs({G2: 0})[:lx, lx:])
        c1 = sp.expand(Pf.subs(sub).subs({G2: 1})[:lx, lx:])
        row["moves_c"] = sp.expand(c1 - c0) != sp.zeros(lx, lx)
        # the sweep: 6 rows x 8 couplings per size
        sweep = {}
        for sigma in SWEEP_SIGMAS:
            for st in SWEEP_ST:
                sb = bench_sub(fx, c, sigma=sigma, st=st)
                cells = []
                for g in SWEEP_G2:
                    Pg = sp.expand(Pf.subs(sb).subs({G2: g}))
                    cells.append((tuple(inertia(Pg)),
                                  sp.expand(Pg[:lx, lx:]).rank()))
                sweep[(sigma, st)] = tuple(cells)
        row["sweep"] = sweep
        row["sweep_rows_reaching_pd"] = sum(
            1 for cells in sweep.values()
            if any(t == (2 * lx, 0, 0) for t, _ in cells))
        row["sweep_rank_c"] = all(rk == lx for cells in sweep.values()
                                  for _, rk in cells)
        row["pd_at_zero_coupling"] = any(
            cells[0][0] == (2 * lx, 0, 0) for cells in sweep.values())
        row["negative_coupling_fails"] = all(
            cells[-1][0] != (2 * lx, 0, 0) for cells in sweep.values())
        row["bench_hundred_fails"] = all(
            cells[SWEEP_G2.index(sp.Integer(100))][0] != (2 * lx, 0, 0)
            for key, cells in sweep.items() if key[0] == BENCH_SIGMA)

        # === GROUND (i): d_2 IS NOT A DIFFERENTIAL ==========================
        d2sq = sclean(smul(d2, d2))
        want = sclean({(lx * ((t + 4) % fx.COVER_T) + y, lx * t + y): -G2 ** 2
                       for t in range(fx.COVER_T) for y in range(lx)})
        D2 = dense(d2, cover, cover)
        row["d2_squared_zero"] = d2sq == {}
        row["d2_squared_is_minus_g2sq"] = sp.expand(
            dense(d2sq, cover, cover) - dense(want, cover, cover)) \
            == sp.zeros(cover, cover)
        row["d2_determinant"] = sp.factor(D2.det())
        row["d2_rank"] = D2.rank()
        row["anticommutator_zero"] = sclean(
            sadd(smul(d1, d2), smul(d2, d1))) == {}
        dsum = sclean(smul(sadd(d1, d2), sadd(d1, d2)))
        row["sum_squared_zero"] = dsum == {}
        row["sum_squared_entries"] = len(dsum)

        # === GROUND (ii): THE CALIBRATION IS BROKEN =========================
        flat = flat_carrier(fx)
        want_cal = MASS * sp.diag(*([1] * lx + [0] * lx))
        defect0 = sp.expand(P0.subs({ST: 0}).subs(flat) - want_cal)
        defect1 = sp.expand(Pf.subs({ST: 0}).subs(flat) - want_cal)
        row["calibration_committed"] = defect0 == sp.zeros(2 * lx, 2 * lx)
        row["calibration_broken"] = defect1 != sp.zeros(2 * lx, 2 * lx)
        row["calibration_defect_diagonal"] = tuple(
            sp.expand(defect1[k, k]) for k in range(2 * lx))
        row["calibration_defect_offdiagonal_zero"] = all(
            defect1[i, j] == 0 for i in range(2 * lx) for j in range(2 * lx)
            if i != j)

        # === GROUND (iii): ZERO TRANSPORT ===================================
        X1 = sp.expand(sp.diff(Pf, G2))
        row["affine_identity"] = sp.expand(
            Pf - P0 - G2 * X1) == sp.zeros(2 * lx, 2 * lx)
        x_free = free_symbols_of(X1)
        row["shim_is_connection_blind"] = not (x_free & {ST, SX, MASS})
        row["shim_hermitian"] = sp.expand(X1 - X1.H) == sp.zeros(2 * lx, 2 * lx)
        row["shim_b_part_zero"] = sp.expand(
            X1[:lx, :lx]) == sp.zeros(lx, lx)
        row["shim_c_rank"] = sp.expand(X1[:lx, lx:]).rank()
        row["shim_corner_inertia"] = tuple(
            inertia(sp.expand(X1[lx:, lx:].subs(sub))))
        holo = connection_gen(fx, I * SX, GRE + I * GIM, ET)
        act_h = fx.quotient_action(holo[(0, 0)], hodge, MASS)
        P0h = sp.expand(fx.pairing(desc, act_h, rows))
        X1h = sp.expand(sp.diff(
            sp.expand(fx.pairing(desc, sadd(act_h, dq), rows)), G2))
        row["committed_part_moves_under_holonomy"] = sp.expand(
            P0h - P0) != sp.zeros(2 * lx, 2 * lx)
        row["shim_holonomy_identical"] = sp.expand(
            X1h - X1) == sp.zeros(2 * lx, 2 * lx)
        # THE UPSTREAM STATEMENT: the addition is already connection-blind at
        # the level of the quotiented ACTION, so EVERY additive diagnostic
        # inherits exactly the same blind addition -- which is why a second
        # diagnostic returns the same disposal.
        Q0 = dense(act, fx.PHYS, fx.PHYS)
        Y1 = sp.expand(sp.diff(dense(sadd(act, dq), fx.PHYS, fx.PHYS), G2))
        row["action_affine"] = sp.expand(
            dense(sadd(act, dq), fx.PHYS, fx.PHYS) - Q0 - G2 * Y1) \
            == sp.zeros(fx.PHYS, fx.PHYS)
        row["action_shim_blind"] = not (
            free_symbols_of(Y1) & {ST, SX, MASS})
        row["action_shim_holonomy_identical"] = sp.expand(
            sp.diff(dense(sadd(act_h, dq), fx.PHYS, fx.PHYS), G2) - Y1) \
            == sp.zeros(fx.PHYS, fx.PHYS)
        # the moment leg: the committed measure's Hermitian part, and the
        # imposed term's, which is EMPTY -- both are anti-Hermitian
        hq = sp.expand((Q0 + Q0.H) / 2)
        row["moment_is_mass_metric"] = sp.expand(
            hq - MASS * dense(fx.quotient(hodge), fx.PHYS, fx.PHYS)) \
            == sp.zeros(fx.PHYS, fx.PHYS)
        row["imposed_moment_part_empty"] = sp.expand(
            (Y1 + Y1.H) / 2) == sp.zeros(fx.PHYS, fx.PHYS)
        # (8,0,0) WITH THE CONNECTION SWITCHED OFF
        zero_conn = []
        zsub = bench_sub(fx, c, st=sp.Integer(0), sx=sp.Integer(0))
        for g in ZERO_CONNECTION_G2:
            Pz = sp.expand(Pf.subs(zsub).subs({G2: g}))
            zero_conn.append((tuple(inertia(Pz)),
                              sp.expand(Pz[:lx, lx:]).rank()))
        row["zero_connection"] = tuple(zero_conn)

        # === GROUND (iv): THE SHIM DISCRIMINATOR FAILS ======================
        # the BARE CONNECTION-BLIND additive shim, with NO ACTION TERM AT ALL
        row["bare_blind_shim_reproduces"] = sp.expand(
            Pf - (P0 + G2 * X1)) == sp.zeros(2 * lx, 2 * lx)
        # ... while the narrower CORNER-DIAGONAL shim of the solve's E5 does
        # not, which is the whole of what E5 excluded
        corner_only = sp.expand(P0 + sp.diag(
            sp.zeros(lx, lx), sp.expand(X1[lx:, lx:]) * G2))
        row["corner_diagonal_shim_fails"] = sp.expand(
            Pf - corner_only) != sp.zeros(2 * lx, 2 * lx)
        Bb = sp.expand(P0.subs(sub)[:lx, :lx])
        C1x = sp.expand(X1[:lx, lx:].subs(sub))
        row["bench_b_inertia"] = tuple(inertia(Bb))
        row["schur_quadratic_inertia"] = tuple(
            inertia(sp.expand(-(C1x.H * Bb.inv() * C1x))))
        window = []
        rows_wanted = WINDOW_LAW[tag] + (DEEP_WINDOW_EXTRA[tag] if deep else ())
        for mass, st, g, _ in rows_wanted:
            sb = bench_sub(fx, c, mass=mass, st=st)
            tri = tuple(inertia(sp.expand(Pf.subs(sb).subs({G2: g}))))
            window.append((mass, st, g, tri == (2 * lx, 0, 0)))
        row["window_law"] = tuple(window)
        row["window_law_wanted"] = tuple(rows_wanted)
        # THE SIGN CONVENTION, PINNED: which orientation g_2 multiplies
        d2b = disp2_operator(fx, I * G2 * sp.eye(lx), backward=True)
        Pb = sp.expand(fx.pairing(desc, sadd(act, first_order(fx, hodge, d2b)),
                                  rows))
        X1b = sp.expand(sp.diff(Pb, G2))
        row["backward_corner_flips_sign"] = sp.expand(
            X1b[lx:, lx:] + X1[lx:, lx:]) == sp.zeros(lx, lx)
        row["backward_corner_inertia"] = tuple(
            inertia(sp.expand(X1b[lx:, lx:].subs(sub))))
        row["backward_window_is_negative"] = all(
            tuple(inertia(sp.expand(Pb.subs(sub).subs({G2: g}))))
            == (2 * lx, 0, 0) for g in (-R(1, 2), -sp.Integer(1))
        ) and all(
            tuple(inertia(sp.expand(Pb.subs(sub).subs({G2: g}))))
            != (2 * lx, 0, 0) for g in (R(1, 2), sp.Integer(1))
        )
        out[tag] = row
    return out


# ---------------------------------------------------------------------------
# F. H4 -- THE INJECTIVITY COMPLETION
# ---------------------------------------------------------------------------
def injectivity_probe(fixtures: dict, benches: dict) -> dict:
    out: dict = {}
    for tag in TAGS:
        fx = fixtures[tag]
        c, lx = SLICE_C, fx.LX
        rows = fx.slice_rows(c, c + 1)
        M = dense(fx.quotient(fx.H_free), fx.PHYS, fx.PHYS)
        support = {(i, j) for i in range(fx.PHYS) for j in range(fx.PHYS)
                   if sp.expand(M[i, j]) != 0}
        xtrivial, xreflecting = [], []
        witness_generic = False
        for lab in fx.involutive:
            if fx.fixed_slice(lab) != c:
                continue
            r = dense(fx.descent(lab), fx.PHYS, fx.PHYS)
            Mth = sp.expand(r * M * r)
            bad = tuple((i, j) for i in range(fx.PHYS)
                        for j in range(fx.PHYS)
                        if (i, j) not in support and sp.expand(Mth[i, j]) != 0)
            entry = (lab, len(bad), bad[0] if bad else None)
            if lab[2] == 1:
                xtrivial.append(entry)
                # THE NARROWING, MEASURED: the offending entry is a NONZERO
                # POLYNOMIAL in the moduli, so it is the GENERIC-moduli
                # statement; at special carriers it can vanish.
                witness = sp.expand(Mth[WITNESS_POSITION[0],
                                        WITNESS_POSITION[1]])
                witness_generic = bool(
                    WITNESS_POSITION not in support
                    and witness != 0
                    and witness.free_symbols)
            else:
                xreflecting.append(entry)
        # THE MECHANISM THAT REPLACES PARITY: injectivity of (shears) -> C
        shears = [fx.B[k] for k in fx.CELLS]
        incident = [fx.B[(t % fx.PHYS_T, x)]
                    for t in (c - 1, c) for x in range(lx)]
        maps = {}
        for name, hodge in (("offregion", fx.H_free),
                            ("region", benches[tag]["hodge"])):
            act = fx.quotient_action(fx.edge_d[(0, 0)], hodge, MASS)
            P = sp.expand(fx.pairing(fx.descent(site_label(fx, c)), act, rows)
                          ).subs({ST: 0, SX: 0})
            C = sp.expand(P[:lx, lx:])
            grid = []
            for i in range(lx):
                for j in range(lx):
                    re, im = sp.expand(C[i, j]).as_real_imag()
                    grid.append([sp.diff(re, s) for s in shears])
                    grid.append([sp.diff(im, s) for s in shears])
            Mm = sp.Matrix(grid)
            live = tuple(str(s) for s in shears if any(
                Mm[k, shears.index(s)] != 0 for k in range(Mm.rows)))
            maps[name] = (Mm.rank(), live, C == sp.zeros(lx, lx))
        # the NAMED class extension, measured and adopted nowhere
        extension = []
        for lab, _, _ in xreflecting:
            P = sp.expand(fx.pairing(fx.descent(lab), benches[tag]["act"],
                                     rows))
            extension.append((
                P[:lx, lx:] == sp.zeros(lx, lx),
                tuple(inertia(sp.expand(P.subs(bench_sub(fx, c))))),
            ))
        out[tag] = {
            "xtrivial": tuple(xtrivial),
            "xreflecting": tuple(xreflecting),
            "witness_generic": witness_generic,
            "maps": maps,
            "incident": tuple(str(s) for s in incident),
            "extension": tuple(extension),
        }
    return out


@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    convention: tuple
    anchors: dict
    links: dict
    inhomogeneous: dict
    disposal: dict
    injectivity: dict
    deep: bool
    exact_no_float: bool
    scope: dict


def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    fixtures = {tag: b165.Fixture(cover_t, lx, tag)
                for tag, cover_t, lx in FIXTURE_SPECS}
    benches: dict = {}
    for tag in TAGS:
        fx = fixtures[tag]
        hodge = b166.ssubs(fx.H_free,
                           b166.region_pin(fx, [SLICE_C - 1, SLICE_C]))
        act = fx.quotient_action(fx.edge_d[(0, 0)], hodge, MASS)
        benches[tag] = {
            "hodge": hodge,
            "act": act,
            "P0": sp.expand(fx.pairing(
                fx.descent(site_label(fx, SLICE_C)), act,
                fx.slice_rows(SLICE_C, SLICE_C + 1))),
        }

    convention = convention_probe()
    anchors = anchor_probe(fixtures, benches)
    links = link_probe(fixtures, benches)
    inhomogeneous = inhomogeneous_probe(fixtures, benches)
    disposal = disposal_probe(fixtures, benches, deep)
    injectivity = injectivity_probe(fixtures, benches)

    scalars: list = [
        BENCH_SIGMA, BENCH_SX, BENCH_ST, BENCH_MASS,
        SWEEP_SIGMAS, SWEEP_ST, SWEEP_G2, ZERO_CONNECTION_G2,
        tuple(row[:3] for row in WINDOW_LAW["8x4"]),
        tuple(row[:3] for row in WINDOW_LAW["12x4"]),
        disposal["8x4"]["calibration_defect_diagonal"],
        disposal["12x4"]["calibration_defect_diagonal"],
        disposal["8x4"]["d2_determinant"],
        disposal["12x4"]["d2_determinant"],
        links["mass_parity"]["8x4"]["inertia"],
        links["mass_parity"]["12x4"]["inertia"],
    ]
    exact = all(no_float(value) for value in scalars)

    return Facts(
        main_head=main_head,
        authority=authority,
        convention=convention,
        anchors=anchors,
        links=links,
        inhomogeneous=inhomogeneous,
        disposal=disposal,
        injectivity=injectivity,
        deep=deep,
        exact_no_float=exact,
        scope=scope_certificate(raw_note()),
    )


