# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
TRANSPORT_KEYS = ("transport_census", "carrying_but_inadmissible")


def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "lane_conventions_uniform": False,
        "link_h1_census_only": False,
        "liveness_law_holds": True,
        "staggered_alternation_holds": True,
        "inhomogeneous_extension_holds": True,
        "route_reopened": False,
        "d2_is_differential": False,
        "calibration_survives": False,
        "h3_carries_transport": False,
        "injectivity_holds": True,
        "b168_sentences_need_narrowing": False,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_convention_uniform":
        # THE BANNER DENIED: the lane asserted to carry ONE inertia convention,
        # which the two-helper comparison on identical matrices forbids
        claims["lane_conventions_uniform"] = True
    elif mutation == "claim_link_census_only":
        # H1 DENIED AS A THEOREM: the link result asserted to be a census only,
        # which the dictionary identity, the liveness law and the three closing
        # theorems forbid
        claims["link_h1_census_only"] = True
    elif mutation == "break_liveness_law":
        # THE LIVENESS LAW DENIED, which the T = 4..8 label-by-label match
        # forbids
        claims["liveness_law_holds"] = False
    elif mutation == "break_staggered_alternation":
        # THE ALTERNATION THEOREM DENIED, which the measured sign patterns and
        # the negative bench diagonal entry forbid
        claims["staggered_alternation_holds"] = False
    elif mutation == "break_inhomogeneous_extension":
        # H2 DENIED: some per-link corner asserted to have a live diagonal,
        # which the 24-cell symbolic measurement forbids
        claims["inhomogeneous_extension_holds"] = False
    elif mutation == "claim_route_reopened":
        # THE SOLVE'S READING RE-ASSERTED: the OS route asserted reopened,
        # which all four disposal grounds independently forbid
        claims["route_reopened"] = True
    elif mutation == "claim_d2_differential":
        # THE CATEGORY ERROR RE-ASSERTED: d_2 asserted to be a differential,
        # which d_2^2 = -g_2^2 S_t^4 and the invertibility forbid
        claims["d2_is_differential"] = True
    elif mutation == "break_calibration_defect":
        # GROUND (ii) DENIED: the calibration asserted preserved, which the
        # exact 2 g_2 / g_2 defect at s_t = 0 on the flat carrier forbids
        claims["calibration_survives"] = True
    elif mutation == "claim_h3_carries_transport":
        # GROUND (iii) DENIED: the H3 addition asserted to carry connection
        # content, which its s_t/s_x/m-freedom, its holonomy invariance and the
        # zero-connection (8,0,0) forbid
        claims["h3_carries_transport"] = True
    elif mutation == "break_injectivity":
        # H4'S MECHANISM DENIED: the shear-to-C map asserted non-injective on
        # the incident sector, which rank 8 of 8 forbids
        claims["injectivity_holds"] = False
    elif mutation == "claim_b168_needs_narrowing":
        # THE ADJUDICATION DENIED: Block 168's two sentences asserted to need
        # re-scoping, which H2 and the g_2 = 0 sweep column forbid
        claims["b168_sentences_need_narrowing"] = True
    elif mutation == "drop_transport_census":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in TRANSPORT_KEYS
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


# ---------------------------------------------------------------------------
# gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def evaluate_gates(facts: Facts, claims: dict, elapsed_ns: int) -> dict:
    authority = facts.authority
    parent_blobs_ok = (
        authority.parent_artifact_blobs
        if claims["parent_pin"] == "resolved"
        else authority.stale_parent_artifact_blobs
    )
    gate_a = bool(
        AUDIT_INPUT_PATHS
        == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_CLOSURE_AUDIT_ONE_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_SHIM_ZERO_DIAGONAL_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "scripts/admissibility_dirac_kahler_shim_zero_diagonal_2026_08_21.py",
        )
        and PARENT_ARTIFACTS == (BLOCK168_NOTE, BLOCK168_RUNNER)
        and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_import_landed
        and authority.parent_pin_is_commit
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok
    )

    pairs, landed_psd, here_psd, orders_differ = facts.convention
    anchors = facts.anchors
    gate_b = bool(
        pairs == (((4, 4, 0), (4, 0, 4)),
                  ((4, 0, 4), (4, 4, 0)),
                  ((0, 8, 0), (0, 0, 8)))
        and landed_psd
        and here_psd
        and orders_differ == (not claims["lane_conventions_uniform"])
        and all(
            anchors[tag]["bench_is_landed"]
            and anchors[tag]["d1_cover_displacements"] == (-1, 0)
            and anchors[tag]["d1_squared_zero"]
            and anchors[tag]["d1_rank"] == D1_RANK[tag]
            and anchors[tag]["cover_dim"] == COVER_DIM[tag]
            and anchors[tag]["corner_hollow"] == CORNER_HOLLOW[tag]
            and anchors[tag]["b_free_of_st"]
            and anchors[tag]["b_is_mass_linear"]
            and anchors[tag]["c_is_linear_in_st"]
            and anchors[tag]["c_is_mass_free"]
            and anchors[tag]["x_trivial"] == PHYS_T[tag]
            and anchors[tag]["link_directions"] == PHYS_T[tag]
            and anchors[tag]["involutive"] == PHYS_T[tag] * (L_X[tag] + 2)
            for tag in TAGS
        )
        and len(TAGS) == 2
        and facts.exact_no_float
    )

    links = facts.links
    census_only = not (
        all(links["dictionary"][tag]["identity"] for tag in TAGS)
        and links["liveness_law"]["ok"]
        and all(row[8] != "UNCLOSED"
                for tag in TAGS for row in links["census"][tag])
    )
    live_rows = tuple(row for tag in TAGS for row in links["census"][tag]
                      if row[3])
    alternation_ok = all(
        signs in ALTERNATING_PATTERNS and negative_entry and is_principal
        for tag in TAGS
        for _, signs, negative_entry, is_principal in links["alternation"][tag]
    )
    transport_rows = tuple(row for tag in TAGS
                           for row in links["transport"][tag])
    gate_c = bool(
        all(
            links["dictionary"][tag]["identity"]
            and links["dictionary"][tag]["free_symbols"] == DICT_SYMBOLS[tag]
            and links["dictionary"][tag]["directions"] == PHYS_T[tag]
            and links["census"][tag] == LINK_CENSUS[tag]
            and links["mass_parity"][tag]["identity"]
            and links["mass_parity"][tag]["mass_linear_diagonal"]
            and links["mass_parity"][tag]["c_nonzero"]
            and links["mass_parity"][tag]["inertia"] == MASS_PARITY_INERTIA
            for tag in TAGS
        )
        and links["liveness_law"]["lx"] == GENERAL_T_LX == 2
        and tuple(row[0] for row in links["liveness_law"]["rows"]) == GENERAL_T
        and tuple(row[1] for row in links["liveness_law"]["rows"]) \
            == LIVE_COUNTS
        and tuple(row[2] for row in links["liveness_law"]["rows"]) == GENERAL_T
        and links["liveness_law"]["ok"] == claims["liveness_law_holds"]
        and len(links["odd_t"]) == len(ODD_T)
        and all(negative and diagonal_free
                for _, _, negative, diagonal_free in links["odd_t"])
        and len(live_rows) == LIVE_CORNERS
        and all(not row[4] for row in live_rows)          # NOT traceless, 4/4
        and alternation_ok == claims["staggered_alternation_holds"]
        and len(transport_rows) == LIVE_CORNERS
        and all(carrier and st and sx and holonomy
                for _, carrier, st, sx, holonomy in transport_rows)
        and census_only == claims["link_h1_census_only"]
        and facts.exact_no_float
    )

    inhomo = facts.inhomogeneous
    cells = {(tag,) + key: value
             for tag in TAGS for key, value in inhomo["cells"][tag].items()}
    extension_holds = all(value[0] for value in cells.values())
    gate_d = bool(
        all(
            inhomo["pins"][tag]["g_pin"]
            and inhomo["pins"][tag]["gh_pin"]
            and inhomo["pins"][tag]["chart_pairs"] == 16
            for tag in TAGS
        )
        and len(cells) == INHOMO_CELLS == 24
        and len(TAGS) * 2 * len(INHOMO_OBJECTS) * len(INHOMO_COUPLINGS) == 24
        and sum(1 for value in cells.values() if not value[1]) \
            == INHOMO_VACUOUS
        and all(value[2] for value in cells.values() if value[1])
        and extension_holds == claims["inhomogeneous_extension_holds"]
        and facts.exact_no_float
    )

    disposal = facts.disposal
    ground_i = all(
        not disposal[tag]["d2_squared_zero"]
        and disposal[tag]["d2_squared_is_minus_g2sq"]
        and disposal[tag]["d2_rank"] == COVER_DIM[tag]
        and sp.expand(disposal[tag]["d2_determinant"]
                      - G2 ** COVER_DIM[tag]) == 0
        and not disposal[tag]["anticommutator_zero"]
        and not disposal[tag]["sum_squared_zero"]
        and disposal[tag]["sum_squared_entries"] == SUM_SQUARED_ENTRIES[tag]
        for tag in TAGS
    )
    ground_ii = all(
        disposal[tag]["calibration_committed"]
        and disposal[tag]["calibration_broken"]
        and disposal[tag]["calibration_defect_offdiagonal_zero"]
        and disposal[tag]["calibration_defect_diagonal"]
        == tuple([sp.Integer(0)] * L_X[tag]
                 + [CALIBRATION_DEFECT[tag] * G2] * L_X[tag])
        for tag in TAGS
    )
    ground_iii = all(
        disposal[tag]["affine_identity"]
        and disposal[tag]["shim_is_connection_blind"]
        and disposal[tag]["committed_part_moves_under_holonomy"]
        and disposal[tag]["shim_holonomy_identical"]
        and disposal[tag]["action_affine"]
        and disposal[tag]["action_shim_blind"]
        and disposal[tag]["action_shim_holonomy_identical"]
        and all(triple == (2 * L_X[tag], 0, 0) and rank == L_X[tag]
                for triple, rank in disposal[tag]["zero_connection"])
        for tag in TAGS
    )
    ground_iv = all(
        disposal[tag]["bare_blind_shim_reproduces"]
        and disposal[tag]["corner_diagonal_shim_fails"]
        and disposal[tag]["shim_hermitian"]
        and disposal[tag]["shim_b_part_zero"]
        and disposal[tag]["shim_c_rank"] == L_X[tag]
        and disposal[tag]["shim_corner_inertia"] == ADDED_CORNER_INERTIA
        and disposal[tag]["bench_b_inertia"] == ADDED_CORNER_INERTIA
        and disposal[tag]["schur_quadratic_inertia"] \
            == SCHUR_QUADRATIC_INERTIA
        and disposal[tag]["window_law"] == disposal[tag]["window_law_wanted"]
        for tag in TAGS
    )
    grounds = (ground_i, ground_ii, ground_iii, ground_iv)
    reopening_stands = not any(grounds)
    d2_is_differential = all(disposal[tag]["d2_squared_zero"] for tag in TAGS)
    calibration_survives = all(
        not disposal[tag]["calibration_broken"] for tag in TAGS)
    carries_transport = not ground_iii
    gate_e = bool(
        all(
            disposal[tag]["displacements"] == DISPLACEMENTS[tag]
            and not disposal[tag]["touches_b"]
            and disposal[tag]["touches_c"]
            and disposal[tag]["corner_diagonal_entry"]
            and disposal[tag]["corner_not_traceless"]
            and disposal[tag]["cross_not_traceless"]
            and disposal[tag]["cross_diagonal_w_is_traceless"]
            and disposal[tag]["same_hermiticity_class"]
            and disposal[tag]["moves_c"]
            and disposal[tag]["sweep_rows_reaching_pd"] == SWEEP_ROWS
            and disposal[tag]["sweep_rank_c"]
            and not disposal[tag]["pd_at_zero_coupling"]
            and disposal[tag]["negative_coupling_fails"]
            and disposal[tag]["bench_hundred_fails"]
            and disposal[tag]["moment_is_mass_metric"]
            and disposal[tag]["imposed_moment_part_empty"]
            and disposal[tag]["backward_corner_inertia"]
            == (0, L_X[tag], 0)
            and disposal[tag]["backward_window_is_negative"]
            for tag in TAGS
        )
        and len(SWEEP_SIGMAS) * len(SWEEP_ST) == SWEEP_ROWS == 6
        and sum(grounds) == DISPOSAL_GROUNDS == 4
        and reopening_stands == claims["route_reopened"]
        and d2_is_differential == claims["d2_is_differential"]
        and calibration_survives == claims["calibration_survives"]
        and carries_transport == claims["h3_carries_transport"]
        and facts.exact_no_float
    )

    inj = facts.injectivity
    injective = all(
        inj[tag]["maps"]["offregion"][0] == INCIDENT_SHEARS
        and set(inj[tag]["maps"]["offregion"][1]) == set(inj[tag]["incident"])
        for tag in TAGS
    )
    gate_f = bool(
        all(
            len(inj[tag]["xtrivial"]) == 2
            and all(count == FORBIDDEN_POSITIONS[tag]
                    and position == WITNESS_POSITION
                    for _, count, position in inj[tag]["xtrivial"])
            and inj[tag]["witness_generic"]
            and len(inj[tag]["xreflecting"]) == EX_MINUS_LABELS
            and all(count == 0 for _, count, _ in inj[tag]["xreflecting"])
            and inj[tag]["maps"]["region"][0] == 0
            and inj[tag]["maps"]["region"][2]
            and len(inj[tag]["incident"]) == INCIDENT_SHEARS
            and tuple(triple for _, triple in inj[tag]["extension"])
            == EX_MINUS_INERTIA[tag]
            and all(not c_zero for c_zero, _ in inj[tag]["extension"])
            for tag in TAGS
        )
        and injective == claims["injectivity_holds"]
        and facts.exact_no_float
    )

    # THE ADJUDICATION.  Sentence 1 quantifies over objects built from the
    # COMMITTED differential; sentence 2 over CARRIERS at fixed committed
    # objects.  Both are measured here, and neither is touched by H3.
    sentence_one_holds = bool(
        all(value[0] for value in cells.values())        # per-link corners
        and not d2_is_differential                       # H3 is out-of-class
        and all(disposal[tag]["displacements"] != (-1, 0) for tag in TAGS)
    )
    sentence_two_holds = bool(
        all(not disposal[tag]["pd_at_zero_coupling"] for tag in TAGS)
        and all(disposal[tag]["affine_identity"] for tag in TAGS)
    )
    corrections_earned = sum((
        all(disposal[tag]["cross_not_traceless"] for tag in TAGS),      # E1
        all(disposal[tag]["moves_c"] for tag in TAGS),                  # E7
    ))
    needs_narrowing = not (sentence_one_holds and sentence_two_holds)
    gate_g = bool(
        sentence_one_holds
        and sentence_two_holds
        and corrections_earned == SCOPE_CORRECTIONS == 2
        and not reopening_stands
        and all(anchors[tag]["d1_cover_displacements"] == (-1, 0)
                for tag in TAGS)
        and needs_narrowing == claims["b168_sentences_need_narrowing"]
        and facts.exact_no_float
    )

    required = tuple(claims["required_scope_keys"])
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        set(facts.scope) == set(required)
        and all(facts.scope[key] for key in required)
        and authority.note_at_final_path
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        and N5_FENCE.count("\n") + 1 <= 10
        and N5_FENCE.count("\n") + 1 >= 8
        and POOL_TWO_LEADS == 5
        and REMAINING_AXES == 2
        and elapsed_ns <= budget * 1_000_000_000
    )

    return {"A": gate_a, "B": gate_b, "C": gate_c, "D": gate_d,
            "E": gate_e, "F": gate_f, "G": gate_g, "H": gate_h}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    parser.add_argument(
        "--deep",
        action="store_true",
        help="the wider window-law pool and the longer runtime budget; the "
             "baseline runs a disclosed SAMPLE of the carrier sweep and of the "
             "window-law rows",
    )
    arguments = parser.parse_args()
    mutation = arguments.mutation
    started_ns = time.monotonic_ns()

    # Every measurement happens once, before any mutation flag is consulted, so
    # a mutation can only rewrite a CLAIM.  No gate can cascade into another
    # because no gate feeds a measurement.
    facts = measure(arguments.deep)
    elapsed_ns = time.monotonic_ns() - started_ns

    raw_gates = evaluate_gates(facts, build_claims(""), elapsed_ns)
    gate_values = dict(raw_gates)
    if mutation:
        target = MUTATION_GATE[mutation]
        gate_values = evaluate_gates(facts, build_claims(mutation), elapsed_ns)
        changed = {
            key for key in raw_gates if raw_gates[key] != gate_values[key]
        }
        if changed - {target} or gate_values[target]:
            raise AssertionError("mutation did not fail exactly its own gate")

    links = facts.links
    inhomo = facts.inhomogeneous
    disposal = facts.disposal
    inj = facts.injectivity

